// Basic adapter usage (for-await consumer)
const adapter = new StreamSwapAdapter<string>();
adapter.swap(fetchStreamA()); // fetchStreamA returns AsyncIterable<string> or ReadableStream wrapper
(async () => {
  for await (const chunk of adapter) {
    console.log('got', chunk);
    if (shouldSwapBasedOn(chunk)) {
      adapter.swap(fetchStreamB(), { drainPolicy: 'drain' });
    }
  }
})();

// ReadableStream facade for browser consumers
const adapter = new StreamSwapAdapter<Uint8Array>();
const rs = adapter.asReadableStream();
const reader = rs.getReader();
// consumption via reader.read() remains the same even if adapter.swap() is called underneath

// Cancellation propagation example
const adapter = new StreamSwapAdapter();
const ctr = adapter.getAbortController();
adapter.swap(streamThatSupportsAbort(ctr.signal));
setTimeout(() => ctr.abort(), 5000); // aborts underlying source(s) and rejects pending reads
